window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-28e9f5c7b7fc433f"]={"versions": [{"id": "FIG-28e9f5c7b7fc433f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Timing Extensions Spezifikation (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es modelliert das Metamodell zur Spezifikation konkreter Muster für Ereignisauslösungen (<code>ConcretePatternEventTriggering</code>) als Spezialisierung oder im Kontext von <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei zentrale Entitäten und ihre Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>ConcretePatternEventTriggering</code> (mit Stereotyp/Kontextangabe <code>EventTriggeringConstraint</code> oben rechts im Klassenrumpf).</li>\n<li><code>MultidimensionalTime</code>: Repräsentiert mehrdimensionale Zeitangaben mit den Attributen:</li>\n<li><code>+ cseCode: CseCodeType</code> (Kardinalität 1)</li>\n<li><code>+ cseCodeFactor: Integer</code> (Kardinalität 1)</li>\n<li>Kompositionen von <code>ConcretePatternEventTriggering</code> auf <code>MultidimensionalTime</code>:</li>\n<li><code>+offset</code>: Kardinalität <code>1..*</code></li>\n<li><code>+patternLength</code>: Kardinalität <code>1</code></li>\n<li><code>+patternPeriod</code>: Kardinalität <code>0..1</code></li>\n<li><code>+patternJitter</code>: Kardinalität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit bzw. Konfigurationszeit beschreibt eine Instanz von <code>ConcretePatternEventTriggering</code> ein Auslösemuster über mindestens einen Zeit-Offset (<code>offset</code> 1..*), eine zwingend definierte Mustergesamtdauer (<code>patternLength</code> 1) sowie optional wiederkehrende Perioden (<code>patternPeriod</code> 0..1) und Jitter-Toleranzen (<code>patternJitter</code> 0..1), basierend auf diskreten oder kontinuierlichen Zeitbasen (<code>cseCode</code>, <code>cseCodeFactor</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Metamodell-Definition für Timing-Modelle der AUTOSAR Adaptive Platform. Werkzeuge müssen sicherstellen, dass bei jeder <code>ConcretePatternEventTriggering</code>-Instanz mindestens ein <code>offset</code>-Element sowie exakt ein <code>patternLength</code>-Element vorhanden sind. Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> der Entität <code>MultidimensionalTime</code> sind obligatorisch anzugeben.</p>"}, {"id": "FIG-a7e6d4fb3e084271", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Timing Extensions Spezifikation (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es modelliert das Metamodell zur Spezifikation konkreter Muster für Ereignisauslösungen (<code>ConcretePatternEventTriggering</code>) als Spezialisierung oder im Kontext von <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei zentrale Entitäten und ihre Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>ConcretePatternEventTriggering</code> (mit Stereotyp/Kontextangabe <code>EventTriggeringConstraint</code> oben rechts im Klassenrumpf).</li>\n<li><code>MultidimensionalTime</code>: Repräsentiert mehrdimensionale Zeitangaben mit den Attributen:</li>\n<li><code>+ cseCode: CseCodeType [0..1]</code></li>\n<li><code>+ cseCodeFactor: Integer [0..1]</code></li>\n<li>Kompositionen von <code>ConcretePatternEventTriggering</code> auf <code>MultidimensionalTime</code>:</li>\n<li><code>+offset</code>: Kardinalität <code>0..*</code></li>\n<li><code>+patternLength</code>: Kardinalität <code>0..1</code></li>\n<li><code>+patternPeriod</code>: Kardinalität <code>0..1</code></li>\n<li><code>+patternJitter</code>: Kardinalität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit bzw. Konfigurationszeit beschreibt eine Instanz von <code>ConcretePatternEventTriggering</code> ein Auslösemuster über beliebige Zeit-Offsets (<code>offset</code> 0..*), eine optionale Musterlänge (<code>patternLength</code> 0..1), eine optionale Periode (<code>patternPeriod</code> 0..1) und optionale Jitter-Toleranzen (<code>patternJitter</code> 0..1), basierend auf Zeitdefinitionen mit optional spezifizierten Parametern (<code>cseCode</code> [0..1], <code>cseCodeFactor</code> [0..1]).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Metamodell-Definition für Timing-Modelle der AUTOSAR Adaptive Platform. Werkzeuge dürfen für <code>offset</code> leere Mengen zulassen (Kardinalität <code>0..*</code>) und müssen <code>patternLength</code> als optional behandeln (Kardinalität <code>0..1</code>). Ebenso sind die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> optional (<code>[0..1]</code>).</p>"}], "trans": [{"from": "FIG-28e9f5c7b7fc433f", "to": "FIG-a7e6d4fb3e084271", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>MultidimensionalTime</code>: Multiplizität des Attributs <code>cseCode: CseCodeType</code> von implizit 1 auf explizit <code>[0..1]</code> geändert.</li>\n<li><code>MultidimensionalTime</code>: Multiplizität des Attributs <code>cseCodeFactor: Integer</code> von implizit 1 auf explizit <code>[0..1]</code> geändert.</li>\n<li><code>ConcretePatternEventTriggering</code>: Multiplizität der Kompositionsrolle <code>+offset</code> zu <code>MultidimensionalTime</code> von <code>1..<em></code> auf <code>0..</em></code> gelockert.</li>\n<li><code>ConcretePatternEventTriggering</code>: Multiplizität der Kompositionsrolle <code>+patternLength</code> zu <code>MultidimensionalTime</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}]};
